/*** Reject module specifiers and export names outside the safe static named-import subset. */
export function assertStaticImportBinding(
  module: string,
  exportName: string,
  description: string,
): void {
  if (
    !SAFE_MODULE.test(module) ||
    module.includes('\\') ||
    module.split('/').slice(1).includes('..')
  ) {
    throw new Error(`${description} has an unsafe module specifier.`);
  }
  if (!SAFE_EXPORT_NAME.test(exportName)) {
    throw new Error(`${description} has an invalid exported symbol.`);
  }
}

const SAFE_MODULE =
  /^(?:@\/[A-Za-z0-9_./-]+|\.{1,2}\/[A-Za-z0-9_./-]+|@?[A-Za-z0-9][A-Za-z0-9._-]*(?:\/[A-Za-z0-9._-]+)*)$/u;
const SAFE_EXPORT_NAME = /^[A-Za-z_$][A-Za-z0-9_$]*$/u;
